import { describe, it, expect, vi } from 'vitest';

// Pure functions only — keep the real Supabase client out of the test.
vi.mock('@/lib/supabase', () => ({ supabase: {} }));

import {
  occurrenceDate,
  previewOccurrences,
  isValidISODate,
  describeFrequency,
  presetKeyFor,
  monthlyValue,
  formatTimeLabel,
  autoInvoiceReadiness,
  validateAgreementInput,
  friendlyRpcError,
  zonedToUtcISO,
  utcToZonedParts,
  type AgreementInput,
} from './recurringJobs';

// Expected values below were generated by public.recurring_occurrence_date()
// on PostgreSQL 16 for n = 0..5 — the cron's source of truth.
const PG_REFERENCE: [string, 'week' | 'month' | 'year', number, string[]][] = [
  [
    '2026-12-30',
    'week',
    1,
    ['2026-12-30', '2027-01-06', '2027-01-13', '2027-01-20', '2027-01-27', '2027-02-03'],
  ],
  [
    '2027-01-15',
    'month',
    3,
    ['2027-01-15', '2027-04-15', '2027-07-15', '2027-10-15', '2028-01-15', '2028-04-15'],
  ],
  [
    '2027-01-31',
    'month',
    1,
    ['2027-01-31', '2027-02-28', '2027-03-31', '2027-04-30', '2027-05-31', '2027-06-30'],
  ],
  [
    '2027-03-01',
    'week',
    2,
    ['2027-03-01', '2027-03-15', '2027-03-29', '2027-04-12', '2027-04-26', '2027-05-10'],
  ],
  [
    '2027-08-31',
    'month',
    6,
    ['2027-08-31', '2028-02-29', '2028-08-31', '2029-02-28', '2029-08-31', '2030-02-28'],
  ],
  [
    '2027-12-31',
    'month',
    2,
    ['2027-12-31', '2028-02-29', '2028-04-30', '2028-06-30', '2028-08-31', '2028-10-31'],
  ],
  [
    '2028-02-29',
    'year',
    1,
    ['2028-02-29', '2029-02-28', '2030-02-28', '2031-02-28', '2032-02-29', '2033-02-28'],
  ],
];

describe('occurrenceDate (matches Postgres)', () => {
  it.each(PG_REFERENCE)('%s every %s×%i', (start, unit, count, expected) => {
    const actual = [0, 1, 2, 3, 4, 5].map((n) => occurrenceDate(start, unit, count, n));
    expect(actual).toEqual(expected);
  });

  it('never drifts: month-end anchors recover after a short month', () => {
    expect(occurrenceDate('2027-01-31', 'month', 1, 2)).toBe('2027-03-31');
  });
});

describe('previewOccurrences', () => {
  const agreement = {
    start_date: '2027-01-31',
    end_date: null,
    interval_unit: 'month' as const,
    interval_count: 1,
  };

  it('returns the requested number of dates from the given index', () => {
    const list = previewOccurrences(agreement, 1, 3);
    expect(list).toEqual([
      { n: 1, date: '2027-02-28' },
      { n: 2, date: '2027-03-31' },
      { n: 3, date: '2027-04-30' },
    ]);
  });

  it('stops at the end date (inclusive)', () => {
    const list = previewOccurrences({ ...agreement, end_date: '2027-03-31' }, 0, 10);
    expect(list.map((o) => o.date)).toEqual(['2027-01-31', '2027-02-28', '2027-03-31']);
  });

  it('returns nothing when already past the end date', () => {
    expect(previewOccurrences({ ...agreement, end_date: '2027-01-01' }, 0, 5)).toEqual([]);
  });
});

describe('helpers', () => {
  it('validates ISO dates strictly', () => {
    expect(isValidISODate('2028-02-29')).toBe(true);
    expect(isValidISODate('2027-02-29')).toBe(false);
    expect(isValidISODate('2027-13-01')).toBe(false);
    expect(isValidISODate('27-1-1')).toBe(false);
  });

  it('describes frequencies and maps presets', () => {
    expect(describeFrequency('month', 3)).toBe('Quarterly');
    expect(describeFrequency('week', 3)).toBe('Every 3 weeks');
    expect(describeFrequency('year', 1)).toBe('Annually');
    expect(presetKeyFor('week', 2)).toBe('biweekly');
    expect(presetKeyFor('week', 5)).toBe('custom');
  });

  it('normalizes revenue to a monthly value', () => {
    expect(
      monthlyValue({ price_amount: 100, interval_unit: 'month', interval_count: 1 }),
    ).toBeCloseTo(100);
    expect(
      monthlyValue({ price_amount: 300, interval_unit: 'month', interval_count: 3 }),
    ).toBeCloseTo(100);
    expect(
      monthlyValue({ price_amount: 1200, interval_unit: 'year', interval_count: 1 }),
    ).toBeCloseTo(100);
    expect(
      monthlyValue({ price_amount: 50, interval_unit: 'week', interval_count: 1 }),
    ).toBeCloseTo((50 * 52) / 12);
    expect(monthlyValue({ price_amount: null, interval_unit: 'month', interval_count: 1 })).toBe(0);
  });

  it('formats times', () => {
    expect(formatTimeLabel('09:00')).toBe('9:00 AM');
    expect(formatTimeLabel('00:30:00')).toBe('12:30 AM');
    expect(formatTimeLabel('13:05')).toBe('1:05 PM');
  });

  it('maps database errors to friendly messages', () => {
    expect(friendlyRpcError({ code: '23P01', message: 'slot_conflict' })).toMatch(/already booked/);
    expect(friendlyRpcError({ message: 'job_already_started' })).toMatch(/already started/);
    expect(friendlyRpcError({ message: 'not_authorized', code: '42501' })).toMatch(/permission/);
    expect(friendlyRpcError(new Error('weird'))).toMatch(/try again/);
  });
});

describe('validation', () => {
  const valid: AgreementInput = {
    customerId: null,
    customerName: 'Ann Lee',
    customerPhone: '555-0100',
    customerEmail: 'ann@example.com',
    address: '1 Main St',
    title: 'Annual HVAC tune-up',
    serviceType: 'HVAC',
    notes: '',
    intervalUnit: 'year',
    intervalCount: 1,
    startDate: '2027-06-01',
    endDate: null,
    preferredTime: '09:00',
    timezone: 'America/Chicago',
    durationMinutes: 60,
    preferredTechnicianId: null,
    priceAmount: 150,
    autoInvoice: true,
    leadTimeDays: 14,
  };
  const today = '2027-05-01';

  it('accepts a valid agreement', () => {
    expect(validateAgreementInput(valid, today)).toBeNull();
  });

  it('rejects each invalid field with a specific message', () => {
    expect(validateAgreementInput({ ...valid, customerName: ' ' }, today)).toMatch(/name/);
    expect(validateAgreementInput({ ...valid, address: '' }, today)).toMatch(/address/);
    expect(validateAgreementInput({ ...valid, title: '' }, today)).toMatch(/title/);
    expect(validateAgreementInput({ ...valid, customerEmail: 'nope' }, today)).toMatch(/email/);
    expect(validateAgreementInput({ ...valid, intervalCount: 0 }, today)).toMatch(/interval/);
    expect(validateAgreementInput({ ...valid, startDate: '2027-02-30' }, today)).toMatch(
      /start date/,
    );
    expect(validateAgreementInput({ ...valid, startDate: '2027-04-01' }, today)).toMatch(/past/);
    expect(validateAgreementInput({ ...valid, endDate: '2027-05-01' }, today)).toMatch(/end date/);
    expect(validateAgreementInput({ ...valid, timezone: 'Mars/Base' }, today)).toMatch(/timezone/);
    expect(validateAgreementInput({ ...valid, durationMinutes: 5 }, today)).toMatch(/Duration/);
    expect(validateAgreementInput({ ...valid, leadTimeDays: 200 }, today)).toMatch(/ahead/);
    expect(validateAgreementInput({ ...valid, priceAmount: -1 }, today)).toMatch(/price/);
  });

  it('lets an existing agreement keep a past start date when editing', () => {
    expect(
      validateAgreementInput({ ...valid, id: 'x', startDate: '2027-04-01' }, today),
    ).toBeNull();
  });

  it('requires price and contact info for auto-invoicing', () => {
    expect(
      autoInvoiceReadiness({ priceAmount: 0, customerEmail: 'a@b.co', customerPhone: '' }).ok,
    ).toBe(false);
    expect(autoInvoiceReadiness({ priceAmount: 50, customerEmail: '', customerPhone: '' }).ok).toBe(
      false,
    );
    expect(
      autoInvoiceReadiness({ priceAmount: 50, customerEmail: '', customerPhone: '555' }).ok,
    ).toBe(true);
    expect(validateAgreementInput({ ...valid, priceAmount: null }, today)).toMatch(/price/);
    expect(
      validateAgreementInput({ ...valid, priceAmount: null, autoInvoice: false }, today),
    ).toBeNull();
  });
});

describe('timezone conversion', () => {
  it('converts wall-clock time to UTC across DST', () => {
    expect(zonedToUtcISO('2027-07-01', '09:00', 'America/Chicago')).toBe(
      '2027-07-01T14:00:00.000Z',
    );
    expect(zonedToUtcISO('2027-01-15', '09:00', 'America/Chicago')).toBe(
      '2027-01-15T15:00:00.000Z',
    );
    expect(zonedToUtcISO('2027-07-01', '09:00', 'Europe/Berlin')).toBe('2027-07-01T07:00:00.000Z');
    expect(zonedToUtcISO('2027-06-01', '12:30', 'UTC')).toBe('2027-06-01T12:30:00.000Z');
    expect(zonedToUtcISO('2027-06-01', '08:00', 'Asia/Kolkata')).toBe('2027-06-01T02:30:00.000Z');
  });

  it('round-trips through utcToZonedParts', () => {
    const iso = zonedToUtcISO('2027-11-07', '10:15', 'America/Los_Angeles');
    expect(utcToZonedParts(iso, 'America/Los_Angeles')).toEqual({
      date: '2027-11-07',
      time: '10:15',
    });
  });

  it('rejects malformed input', () => {
    expect(() => zonedToUtcISO('nope', '09:00', 'UTC')).toThrow();
  });
});
